-- migrate:no-transaction
-- Index for orders.customer_id. Built CONCURRENTLY so writes to orders keep flowing; this cannot run in a transaction.
-- It serves the foreign key checks on customer deletes and GET /customers/:id/orders.
-- A failed build leaves an INVALID index behind, so drop any leftover before retrying.
SET lock_timeout = '5s';

DROP INDEX CONCURRENTLY IF EXISTS orders_customer_id_idx;
CREATE INDEX CONCURRENTLY orders_customer_id_idx ON orders (customer_id);

