/** A directory holding only the migrations that predate 0005, to simulate production before the deploy. */
async function legacyMigrationsDir(): Promise<string> {
  const dir = await mkdtemp(join(tmpdir(), 'legacy-migrations-'))
  for (const file of PRE_CONSTRAINT_FILES) await copyFile(join(MIGRATIONS, file), join(dir, file))
