test('a failed validation leaves the file unrecorded, and re-running after the fix completes it', async () => {
  const db = new PGlite()
  await migrate(db, await legacyMigrationsDir())
  const ana = await insertCustomer(db, 'ana@example.com')
  await db.query(`INSERT INTO orders (customer_id, total_cents) VALUES ($1, -5)`, [ana])

  await assert.rejects(migrate(db, MIGRATIONS), /orders_total_cents_nonnegative/)
  const recorded = await db.query('SELECT filename FROM schema_migrations ORDER BY filename')
  assert.ok(
    !recorded.rows.some((r) => (r as { filename: string }).filename.startsWith('0006_')),
    '0006 must not be recorded after a failed validation',
  )

  await db.query('UPDATE orders SET total_cents = 0 WHERE total_cents < 0')
  assert.deepEqual(await migrate(db, MIGRATIONS), ['0006_orders_customer_fk_and_total_check.sql'])
})
